#!/usr/bin/env python3
"""Apply the n = 9 addendum to the live #778 entry (title, summary, body paragraphs, labels, card). Every anchor asserted once.
Usage: apply778_n9.py <worktree-root> [--dry-run]. Reads the numbers from the checker log + solver log; refuses unless the checker said ACCEPT."""
import sys, re, os
R=sys.argv[1].rstrip('/'); dry='--dry-run' in sys.argv
LOG=os.path.expanduser('~/MathDyad/erdos778/logs/check_n9_clique.log'); SOL=os.path.expanduser('~/MathDyad/erdos778/logs/n9_clique.out')
acc=open(LOG).read().strip(); assert acc.startswith('ACCEPT :: ACCEPT winner=bob n=9 mode=clique'), f"checker did not ACCEPT: {acc[:200]!r}"
m=re.search(r"(\d+) Alice-to-move positions explored, (\d+) terminal leaves, (\d+) cutoff leaves, (\d+) certificate entries \((\d+) rows, (\d+) duplicate rows\) \[check778c, nauty ([^,]+), threads (\d+), (\d+) s\]", acc); assert m, acc
NODES,LEAVES,CUTS,ENTRIES,ROWS,DUPS,NAUTY,THREADS,SECS=[int(x) if x.isdigit() else x for x in m.groups()]
sol=open(SOL).read(); assert 'RESULT: BOB WINS' in sol and 'n=9' in sol
ms=re.search(r"nodes=(\d+) memo=(\d+) canonCalls=(\d+) orderings=(\d+) cutBob=(\d+) cutAlice=(\d+) time=([\d.]+)s", sol); SN,SM,SC,SO,SB,SA,ST=ms.groups()
REF=os.environ.get('REF_SENTENCE','')  # the checker-code referee verdict sentence, set from the report
def f(x): return f"{int(x):,}"
secs_min=f"{SECS/60:.0f}"
print(f"checker: {f(NODES)} positions, {f(LEAVES)} terminal, {f(CUTS)} cutoffs, {f(ENTRIES)} entries, {f(ROWS)} rows, {DUPS} dups, nauty {NAUTY}, {THREADS} threads, {SECS}s; solver: {f(SN)} nodes, {f(SM)} memo, {ST}s")
IDX=f"{R}/src/index.js"
def edit(old,new,tag):
    s=open(IDX).read(); n=s.count(old); assert n==1, f"{tag}: anchor matched {n} times"; s=s.replace(old,new,1)
    if not dry: open(IDX,'w').write(s)
    print("  replaced:",tag)
# title
edit('title: "#778: Bob wins the (1:2) clique game on K₈ — exact, certified, two engines and an independent checker — and the live large-n claim',
     'title: "#778: Bob wins the (1:2) clique game on K₈ and K₉ — exact, certified: two engines, two independent checkers — and the live large-n claim', "title")
# summary
edit('so this is the first value where Bob has to win the clique game as such.",',
     f'so this is the first value where Bob has to win the clique game as such. Later the same day n = 9 fell too: Bob wins on K₉ — {f(SN)} nodes, {f(SM)} positions up to isomorphism, 77 minutes on one core — with a {f(ENTRIES)}-position strategy certificate accepted by a second independent checker (C++ on nauty, written for the purpose because the first one would have needed about forty hours; it reproduces the first checker\'s n = 8 counts exactly and rejects the same mutations). The first open value is now n = 10.",', "summary")
# the running-sentence → the n = 9 paragraph
edit('<em>n</em> = 9 (36 edges, Alice gets 12) is running on the same engine as this is written; its verdict and certificate check are appended here when they land.</p>',
     f'''</p>

<p><strong>Then <em>n</em> = 9, the same afternoon.</strong> Thirty-six edges, Alice gets twelve. The same engine, one core at the lowest priority: <strong>BOB WINS at <em>n</em> = 9</strong> after {f(SN)} nodes and {f(SM)} canonical positions, {f(SC)} canonical-form calls, in {float(ST)/60:.0f} minutes — about 380 times the <em>n</em> = 8 search (824,319 nodes), which is the number that says <em>n</em> = 10 (45 edges, Alice gets 15) is out of reach for this engine on this box: on that growth it would be on the order of 10<sup>11</sup> nodes. The certificate has {f(ENTRIES)} Bob-to-move positions (1, 5, 66, 920, 11,839, 127,452, 642,765, 3,448,214, 7,691,785, 7,447,176, 1,416,365 and 16,257 after Alice's first to twelfth edge; 597 MB, SHA-256 <code>3398b312…560c5</code> — too large for the repository, regenerated by <code>solve778 --n 9 --cert</code> in 77 minutes). The Python checker above would have needed about forty hours on it, so we wrote a second independent checker for the occasion — C++ on nauty's <code>densenauty</code> ({NAUTY}), its own clique enumeration, its own derivation of both cutoffs, a level-by-level walk of every Alice move at every Alice-to-move position, the recorded reply transported back through nauty's labelling — and calibrated it before trusting it: on every <em>n</em> = 8 run it reports the Python checker's counts to the digit (122,288 / 0 / 57,512 / 210,325; cutoff-free 145,749 / 2,719 / 0 / 336,027), it accepts the <em>n</em> = 6, 7 and <em>n</em> = 7 triangle certificates, it rejects the deleted-entry, fabricated and thirty-swap mutations, and its canonical key agrees with a brute-force isomorphism oracle (all 7! relabellings) on 400 random pairs, including pairs built to share both colour classes' graphs but not the matching between them. That last control is there because the first draft of the key read the two layers off nauty's canonical graph and dropped the rung matching — an incomplete invariant that collided distinct positions; the <em>n</em> = 7 control caught it in under a second, which is what controls are for. On the <em>n</em> = 9 certificate: <strong>ACCEPT</strong> — {f(NODES)} Alice-to-move positions walked, every transported reply free, {f(LEAVES)} full boards{(" each with α(<em>R</em>) &gt; ω(<em>R</em>)" if LEAVES else "")}, {f(CUTS)} leaves closed by the checker's own re-derived Bob cutoff, {f(ENTRIES)} classes loaded ({DUPS} duplicate rows), {secs_min} minutes on {THREADS} threads. As with the first <em>n</em> = 8 verdict, this one rests on the cutoff (two independent derivations of it, now in two languages); a cutoff-free run at <em>n</em> = 9 — the solver playing every line to a full board, then the checker walking that certificate with its cutoffs off, as we did at <em>n</em> = 8 — was started on one core as this was written (about three hours by the <em>n</em> = 8 ratio, 1,445,647 nodes against 824,319); this sentence is updated when it lands.{(' ' + REF) if REF else ''}</p>''', "n9 paragraph")
# what it leaves open
edit("is every <em>n</em> from 9 to 3<sup>158</sup> − 1, the unbiased game", "is every <em>n</em> from 10 to 3<sup>158</sup> − 1, the unbiased game", "leaves open")
# labels
edit("<em>(d) computer-assisted</em> for <em>n</em> = 8: an exact finite search, a certificate, an\nindependent checker with positive and negative controls, the winner re-derived by the same engine with reversed ordering and with cutoffs off, and independently by the July engine (separate code, Python).",
     "<em>(d) computer-assisted</em> for <em>n</em> = 8 and <em>n</em> = 9: an exact finite search, a certificate, independent checkers (two, in different languages on different nauty bindings) with positive and negative controls; at <em>n</em> = 8 also the winner re-derived by the same engine with reversed ordering and with cutoffs off, and independently by the July engine (separate code, Python); at <em>n</em> = 9 the verdict rests on the checker's re-derived cutoff.", "labels")
edit("the finite gap 9 ≤ <em>n</em> &lt; 3<sup>158</sup> is exactly as open as it was, and nobody should read \"Bob wins at 8\" as evidence about",
     "the finite gap 10 ≤ <em>n</em> &lt; 3<sup>158</sup> is exactly as open as it was, and nobody should read \"Bob wins at 9\" as evidence about", "gap sentence")
edit("What is ours: the <em>n</em> = 8 value, the solver and its certificate, the checker, and the three seat reports.",
     "What is ours: the <em>n</em> = 8 and <em>n</em> = 9 values, the solver and its certificates, the two checkers, and the seat reports.", "what is ours")
# triangle sentence (July engine stopped)
edit("That triangle verdict is from one engine so far; the July engine's triangle solver is running and this sentence is updated when it lands.)",
     "That triangle verdict is from one engine: the July engine's triangle solver was stopped after 2½ hours at 15 GB of memory — its state table grows without bound on a tree thirty times the clique game's — so the sentence rests on the 98-million-node run alone.)", "triangle sentence")
# card
edit('tag: "EXACT VALUE · K₈ DECIDED · CERTIFICATE CHECKED BY A NAUTY-BASED CHECKER · TWO ENGINES, TWO AUTHORS ·', 'tag: "EXACT VALUES · K₈ AND K₉ DECIDED · CERTIFICATES CHECKED BY TWO NAUTY-BASED CHECKERS · TWO ENGINES, TWO AUTHORS ·', "card tag")
edit('title: "Bob wins the (1:2) clique game on K₈ — the first value past the table, and the only decided value between 7 and 3^158",',
     'title: "Bob wins the (1:2) clique game on K₈ and K₉ — the first values past the table, and the only decided values between 7 and 3^158",', "card title")
edit('"development — holds as read under three Opus seats (one hostile) and kernel-replays green here. Everything from 9 to 3^158 − 1 is still open.",',
     f'"development — holds as read under three Opus seats (one hostile) and kernel-replays green here. K₉ followed the same afternoon: {f(SN)} nodes, a {f(ENTRIES)}-position certificate accepted by a second checker. Everything from 10 to 3^158 − 1 is still open.",', "card line")
# links: add the n9 subfolder
edit('{ label: "Verification bundle — solver, certificate, checker + controls, the Lean replay',
     '{ label: "n = 9 files — the C++/nauty checker and its convention test, the solver and checker logs, the certificate profile and SHA-256, the checker-code referee report (repository private at the time of writing — files available on request)", url: "https://github.com/pw/ErdosProblemADay.com/tree/main/verification/778/k8-and-large-n-claim/n9" },\n      { label: "Verification bundle — solver, certificate, checker + controls, the Lean replay', "links")
print("DRY RUN — nothing written" if dry else "WRITTEN")
